class Solution {
public:
    int maxBuilding(int n, vector<vector<int>>& restrictions) {
        restrictions.push_back({1, 0});
        sort(restrictions.begin(), restrictions.end());

        int m = restrictions.size();
        // Left-to-right: each building's height can be at most prev + distance
        for (int i = 1; i < m; i++) {
            long long d = (long long)restrictions[i][0] - restrictions[i-1][0];
            long long limit = (long long)restrictions[i-1][1] + d;
            if (limit < restrictions[i][1])
                restrictions[i][1] = (int)limit;
        }
        // Right-to-left: each building's height can be at most next + distance
        for (int i = m - 2; i >= 0; i--) {
            long long d = (long long)restrictions[i+1][0] - restrictions[i][0];
            long long limit = (long long)restrictions[i+1][1] + d;
            if (limit < restrictions[i][1])
                restrictions[i][1] = (int)limit;
        }

        long long ans = 0;
        // Check peak between each pair of adjacent restricted buildings
        for (int i = 0; i < m - 1; i++) {
            long long a = restrictions[i][0], ha = restrictions[i][1];
            long long b = restrictions[i+1][0], hb = restrictions[i+1][1];
            long long d = b - a;
            long long peak = (ha + hb + d) / 2;
            if (peak > ans) ans = peak;
        }
        // Check tail: from last restricted building to building n
        long long lastPos = restrictions[m-1][0];
        long long lastH = restrictions[m-1][1];
        long long tail = lastH + (n - lastPos);
        if (tail > ans) ans = tail;

        return (int)ans;
    }
};
